fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let len = s.len();
    let mut result = s.clone();

    let L = len - (len % 3); // largest multiple of 3 <= length

    for i in 0..L {
        match i % 3 {
            0 => result[i] = s[i + 1],   // position i = input at i+1
            1 => result[i] = s[i + 1],   // position i = input at i+1
            2 => result[i] = s[i - 2],   // position i = input at i-2
            _ => unreachable!(),          // mod 3 only yields 0,1,2
        }
    }

    // For indices from L to length-1, result[i] is already s[i] due to clone

    result
}